import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { FiUser, FiLock, FiEye, FiEyeOff, FiAlertCircle } from "react-icons/fi"; // Librería de iconos
import API from "../services/api";
import "./Login.css";

function Login() {
  const navigate = useNavigate();

  const [usuario, setUsuario] = useState("");
  const [password, setPassword] = useState("");
  const [mensaje, setMensaje] = useState("");
  const [showPassword, setShowPassword] = useState(false); // Estado para el ojo de la clave

  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      const res = await API.post("/login", {
        usuario,
        password,
      });

      localStorage.setItem("usuario", JSON.stringify(res.data));
      navigate("/dashboard");
    } catch (error) {
      if (error.response) {
        setMensaje(error.response.data.mensaje);
      } else {
        setMensaje("Error de conexión con el servidor");
      }
    }
  };

  return (
    <div className="login-container">
      {/* Sección del Logo mejorada visualmente */}
      <div className="logo-section">
        <img src="/diamond.png" alt="logo" className="diamond-logo" />
        <h1>Esmeraldas Premium</h1>
        <p>Portal de Usuarios</p>
      </div>

      <div className="card fade-in">
        <h2>Iniciar Sesión</h2>

        <form onSubmit={handleLogin}>
          {/* Grupo de Usuario con Icono */}
          <div className="input-group">
            <FiUser className="input-icon" />
            <input
              type="text"
              placeholder="Usuario"
              value={usuario}
              onChange={(e) => setUsuario(e.target.value)}
              required
            />
          </div>

          {/* Grupo de Password con Icono y Ojo */}
          <div className="input-group">
            <FiLock className="input-icon" />
            <input
              type={showPassword ? "text" : "password"}
              placeholder="Contraseña"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
            <button
              type="button"
              className="password-toggle"
              onClick={() => setShowPassword(!showPassword)}
            >
              {showPassword ? <FiEyeOff /> : <FiEye />}
            </button>
          </div>

          <button type="submit" className="login-btn">
            INGRESAR
          </button>
        </form>

        {/* Mensaje de Error Pro */}
        {mensaje && (
          <div className="error-box shake">
            <FiAlertCircle />
            <span>{mensaje}</span>
          </div>
        )}

        <div className="register-link">
          <span>¿No tienes cuenta?</span>
          <Link to="/registro"> Regístrate aquí</Link>
        </div>
      </div>
    </div>
  );
}

export default Login;
